// Spec: polish-deai-humanizer 扩展 — 生成场景去AI味规则（与渲染进程 6 个生成入口同款 JSON-aware 变体）
import { withHumanizerGenerationRules } from '../../../../shared/prompts/humanizerPolish';

// ==================== 常量 ====================

const LOG_PREFIX = '[WorldBookAuthoringService]';

/** PLANNING 阶段等待用户回答超时（10 分钟，spec 要求） */
const CLARIFY_TIMEOUT_MS = 10 * 60 * 1000;

/** 会话总超时（30 分钟，spec 要求） */
const SESSION_TIMEOUT_MS = 30 * 60 * 1000;

/** 单维度连续失败阈值（spec §SubTask 4.6 阻塞计数器） */
const DIMENSION_FAILURE_THRESHOLD = 3;

/** 微型审计触发间隔（每 N 条触发一次，spec "每 3-5 条"） */
const MINI_AUDIT_INTERVAL = 3;

/** LLM 调用最大重试次数（spec "LLM 调用失败重试 3 次"） */
const LLM_MAX_RETRIES = 3;

// ==================== 依赖注入类型 ====================

/**
 * 编排服务所用的世界书工具能力（仅暴露编排真正需要的子集）。
 *
 * 通过结构化类型而非直接导入 worldbookTools，降低耦合并便于测试 mock。
 * 默认实现 `createDefaultAuthoringTools` 用 worldbookTools 的导出函数构造。
 */
export interface IAuthoringTools {
  /** 读取世界书（含 entries），用于审计前获取已生成条目 */
  readWorldBook(
    worldBookPath: string
  ): Promise<{
    name?: string;
    description?: string;
    entries?: Array<Record<string, unknown>>;
  } | null>;

  /** 创建草稿条目（autoGenerated=true，spec §ADDED Requirements 自驱编写阶段） */
  createEntry(args: {
    worldBookPath: string;
    name: string;
    content: string;
    keys: string[];
    secondaryKeys?: string[];
    comment?: string;
    dimensionId?: string;
  }, context: ToolCallContext): Promise<ToolExecutionResult>;

  /** 为已有条目重新生成关键词（用于微型审计发现问题后修复） */
  generateKeywords(args: {
    worldBookPath: string;
    entryUid: string | number;
    keys: string[];
    secondaryKeys?: string[];
  }, context: ToolCallContext): Promise<ToolExecutionResult>;

  /**
   * 网络搜索（可选，Spec: add-agent-web-search-tool §Requirement: 世界书编写智能体集成）。
   *
   * 仅当 `WorldBookAuthoringConfig.enableWebSearch === true` 时由编排服务注入并调用。
   * 为可选方法（`?`）：未启用网络搜索时 `undefined`，编排服务调用前做存在性检查，
   * 既有测试无需 mock 此方法（向后兼容）。
   *
   * @param query 搜索关键词
   * @param maxResults 最大结果条数（可选，默认由实现方决定，通常 5）
   * @returns 搜索结果数组（标题 / 摘要 / URL）。失败时返回空数组（不抛错，由实现方捕获降级）
   */
  webSearch?(query: string, maxResults?: number): Promise<Array<{
    title: string;
    snippet: string;
    url: string;
  }>>;
}

/**
 * 条目生成器（LLM 调用注入点，便于测试 mock）。
 *
 * 职责：根据维度描述 + 已有条目，调用 LLM 生成 N 个新条目的草稿数据（name/content/keys）。
 * 默认实现 `createDefaultEntryGenerator` 使用 AIService.callChatAPI。
 */
export interface IEntryGenerator {
  generateEntriesForDimension(
    dimension: AuthoringDimension,
    plan: AuthoringPlan,
    existingEntries: Array<Record<string, unknown>>,
    targetCount: number,
    signal?: AbortSignal,
    /**
     * 网络搜索补充资料（可选，Spec: add-agent-web-search-tool）。
     *
     * 启用网络搜索时由编排服务在 AUTHORING 阶段按维度名 + 主题派生 query 调用 webSearch 获取，
     * 连同原始 query 一并传入；实现方将其格式化后注入 LLM 系统提示词作为参考上下文。
     * 未启用网络搜索时为 undefined，行为与原实现一致（向后兼容）。
     */
    researchContext?: {
      /** 触发本次搜索的 query（便于日志/调试） */
      query: string;
      /** 搜索结果数组 */
      results: Array<{ title: string; snippet: string; url: string }>;
    }
  ): Promise<Array<{
    name: string;
    content: string;
    keys: string[];
    secondaryKeys?: string[];
    comment?: string;
  }>>;
}

